package com.smartdairy.controller;
import com.smartdairy.entity.Supplier; import com.smartdairy.service.SupplierService; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class SupplierServlet extends HttpServlet {private final SupplierService service=new SupplierService(); protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{Supplier s=read(req);service.create(s);resp.sendRedirect("supplier.jsp?success=true");}catch(Exception e){resp.sendRedirect("supplier.jsp?error="+java.net.URLEncoder.encode(e.getMessage(),"UTF-8"));}} private Supplier read(HttpServletRequest r){Supplier s=new Supplier();s.setName(r.getParameter("name"));s.setMobile(r.getParameter("mobile"));s.setAddress(r.getParameter("address"));s.setAnimalType(r.getParameter("animal_type"));s.setBankDetails(r.getParameter("bank_details"));s.setStatus(r.getParameter("status"));return s;}}
